ALTER TABLE subscription_plan_features DROP CONSTRAINT IF EXISTS chk_subscription_plan_feature_feature;
ALTER TABLE subscription_plan_features ADD CONSTRAINT chk_subscription_plan_feature_feature CHECK (feature IN ('BARCODE_SCANNER','MANUAL_FOOD_LOGGING','FOOD_DIARY','WEIGHT_PROGRESS','WATER_TRACKING','WORKOUT_LOGGING','SAVED_MEAL_TEMPLATES','RECIPE_BUILDER','PUBLIC_RECIPE_LIBRARY','ADVANCED_MACRO_TARGETS','MICRONUTRIENT_DETAILS','DATA_EXPORT','FASTING_BASIC','FASTING_ADVANCED','AI_MEAL_DRAFTS','AI_WORKOUT_PLANNER','AI_RECIPE_GENERATION','AI_MEAL_PREPARATION_GUIDE','AI_NUTRITION_PLAN','AI_INSIGHTS','HEALTH_INTEGRATION','ADVANCED_ANALYTICS','AD_FREE','CUSTOM_FOOD_LIBRARY'));
ALTER TABLE user_subscription_entitlements DROP CONSTRAINT IF EXISTS chk_user_subscription_entitlement_feature;
ALTER TABLE user_subscription_entitlements ADD CONSTRAINT chk_user_subscription_entitlement_feature CHECK (feature IN ('BARCODE_SCANNER','MANUAL_FOOD_LOGGING','FOOD_DIARY','WEIGHT_PROGRESS','WATER_TRACKING','WORKOUT_LOGGING','SAVED_MEAL_TEMPLATES','RECIPE_BUILDER','PUBLIC_RECIPE_LIBRARY','ADVANCED_MACRO_TARGETS','MICRONUTRIENT_DETAILS','DATA_EXPORT','FASTING_BASIC','FASTING_ADVANCED','AI_MEAL_DRAFTS','AI_WORKOUT_PLANNER','AI_RECIPE_GENERATION','AI_MEAL_PREPARATION_GUIDE','AI_NUTRITION_PLAN','AI_INSIGHTS','HEALTH_INTEGRATION','ADVANCED_ANALYTICS','AD_FREE','CUSTOM_FOOD_LIBRARY'));
WITH plans(plan_type) AS (VALUES ('FREE'),('PLUS'),('PRO')), features(feature) AS (VALUES ('BARCODE_SCANNER'),('MANUAL_FOOD_LOGGING'),('FOOD_DIARY'),('WEIGHT_PROGRESS'),('WATER_TRACKING'),('WORKOUT_LOGGING'),('SAVED_MEAL_TEMPLATES'),('RECIPE_BUILDER'),('PUBLIC_RECIPE_LIBRARY'),('FASTING_BASIC'),('CUSTOM_FOOD_LIBRARY'),('AD_FREE'),('ADVANCED_MACRO_TARGETS'),('MICRONUTRIENT_DETAILS'),('DATA_EXPORT'),('FASTING_ADVANCED'),('HEALTH_INTEGRATION'),('ADVANCED_ANALYTICS'),('AI_MEAL_DRAFTS'),('AI_WORKOUT_PLANNER'),('AI_RECIPE_GENERATION'),('AI_MEAL_PREPARATION_GUIDE'),('AI_NUTRITION_PLAN'),('AI_INSIGHTS')) INSERT INTO subscription_plan_features (plan_type,feature,enabled,effective_from,updated_at) SELECT p.plan_type,f.feature,CASE WHEN f.feature IN ('BARCODE_SCANNER','MANUAL_FOOD_LOGGING','FOOD_DIARY','WEIGHT_PROGRESS','WATER_TRACKING','WORKOUT_LOGGING','SAVED_MEAL_TEMPLATES','RECIPE_BUILDER','PUBLIC_RECIPE_LIBRARY','FASTING_BASIC','CUSTOM_FOOD_LIBRARY','AD_FREE') THEN TRUE WHEN p.plan_type IN ('PLUS','PRO') THEN TRUE ELSE FALSE END,CURRENT_DATE,CURRENT_TIMESTAMP FROM plans p CROSS JOIN features f ON CONFLICT (plan_type,feature) DO UPDATE SET enabled=EXCLUDED.enabled,effective_from=EXCLUDED.effective_from,updated_at=CURRENT_TIMESTAMP;
UPDATE subscriptions SET ai_monthly_quota=0 WHERE plan_type='FREE';
UPDATE subscriptions SET ai_monthly_quota=50 WHERE plan_type='PLUS' AND (ai_monthly_quota IS NULL OR ai_monthly_quota=15);
UPDATE subscriptions SET ai_monthly_quota=150 WHERE plan_type='PRO' AND (ai_monthly_quota IS NULL OR ai_monthly_quota=100);
UPDATE user_subscription_entitlements e SET enabled=FALSE,valid_until=CURRENT_DATE-1,updated_at=CURRENT_TIMESTAMP FROM subscriptions s WHERE e.subscription_id=s.id AND s.plan_type='FREE' AND e.enabled=TRUE AND e.feature IN ('AI_MEAL_DRAFTS','AI_WORKOUT_PLANNER','AI_RECIPE_GENERATION','AI_MEAL_PREPARATION_GUIDE','AI_NUTRITION_PLAN','AI_INSIGHTS');
UPDATE user_subscription_entitlements SET enabled=TRUE,updated_at=CURRENT_TIMESTAMP WHERE feature='AD_FREE';
INSERT INTO user_subscription_entitlements (subscription_id,user_id,feature,enabled,source_plan,valid_from,valid_until,created_at,updated_at) SELECT s.id,s.user_id,f.feature,TRUE,s.plan_type,COALESCE(s.start_date,CURRENT_DATE),s.end_date,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM subscriptions s JOIN subscription_plan_features f ON f.plan_type=s.plan_type AND f.enabled=TRUE WHERE s.user_id IS NOT NULL AND s.status IN ('ACTIVE','TRIALING','CANCELED') AND (s.end_date IS NULL OR s.end_date>=CURRENT_DATE) AND NOT EXISTS (SELECT 1 FROM user_subscription_entitlements e WHERE e.subscription_id=s.id AND e.feature=f.feature AND e.enabled=TRUE AND (e.valid_until IS NULL OR e.valid_until>=CURRENT_DATE));